// whatever depends on the date may now read differently. Also whether the sheet is archived, and
// the button a steward archives it with; once archived, every change on the sheet is refused.
function SheetToday({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const sheet = useSheet(sheetId);
  const [input, setInput] = useState('');
  const [error, setError] = useState('');
  const [user] = useUser();

  const once = useOnce();
  const save = useMutation({
    mutationFn: (today: string) =>
      postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/today`, { today }, user),
    onSuccess: (updated) => {
      queryClient.setQueryData(sheetKey(sheetId), updated);
      void queryClient.invalidateQueries({
        queryKey: ['sheet', sheetId],
        predicate: (q) => q.queryKey[2] !== 'info',
      });
    },
    onError: () => setError('That date could not be set as today.'),
  });

  const archive = useMutation({
    mutationFn: () => postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/archive`, {}, user),
    onSuccess: (updated) => queryClient.setQueryData(sheetKey(sheetId), updated),
    onError: () => setError('The sheet could not be archived.'),
  });

  const archiveSheet = () => {
    setError('');
    once((done) => archive.mutate(undefined, { onSettled: done }));
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const today = input.trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      setError('Choose a date for today.');
      return;
    }
    once((done) => save.mutate(today, { onSettled: done }));
  };

  return (
    <form onSubmit={submit} data-testid="sheet-today-form">
      Today: <strong data-testid="sheet-today">{sheet.data?.today ?? ''}</strong>{' '}
      <label>
        Set today{' '}
        <input
          type="date"
          data-testid="sheet-today-input"
          value={input}
          onChange={(e) => {
            setInput(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set
      </button>{' '}
      Archived: <strong data-testid="sheet-archived">{sheet.data ? (sheet.data.archived ? 'yes' : 'no') : ''}</strong>{' '}
      <button type="button" data-testid="sheet-archive" onClick={archiveSheet} disabled={archive.isPending}>
        Archive sheet
      </button>
      {(error || sheet.isError) && (
        <p role="alert" data-testid="sheet-error">
          {error || 'The sheet could not be read.'}
        </p>
      )}
    </form>
  );
}

export const contribution = SheetBody.fill({ order: -100, Component: SheetToday });
import { asString, useSearchParam } from '../../url/useSearchParam';

// The session lives in the URL: `user` is the signed-in name, `sheet` the active sheet id.
export const useUser = () => useSearchParam('user', asString);
export const useSheetId = () => useSearchParam('sheet', asString);
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { useSheetId } from './session';
import { peopleQuery } from '../people/people';
import { claimsQuery } from '../claims/claims';

type Sheet = { id: string };

// Choose a sheet by typing its id and loading it. An id never used before starts an empty sheet;
// loading an id again drops what was cached for it, so the sheet is re-read from the store. The
// sheet becomes the active one only once its people and claims are read, so its rows are on screen
// as soon as its id is.
export function SheetLoader({ onLoaded }: { onLoaded: () => void }) {
  const queryClient = useQueryClient();
  const [sheetId, setSheetId] = useSheetId();
  const [input, setInput] = useState('');
  const [error, setError] = useState('');

  const once = useOnce();
  const load = useMutation({
    mutationFn: async (id: string) => {
      const sheet = await postJson<Sheet>(`/api/sheets/${encodeURIComponent(id)}/load`, {});
      queryClient.removeQueries({ queryKey: ['sheet', sheet.id] });
      await Promise.all([queryClient.fetchQuery(peopleQuery(sheet.id)), queryClient.fetchQuery(claimsQuery(sheet.id))]);
      return sheet;
    },
    onSuccess: (sheet) => {
      setSheetId(sheet.id);
      onLoaded();
    },
    onError: () => setError('That sheet could not be loaded.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const id = input.trim();
    if (id === '') {
      setError('Type a sheet id to load.');
      return;
    }
    once((done) => load.mutate(id, { onSettled: done }));
  };

  return (
    <form onSubmit={submit} data-testid="sheet-form">
      <label>
        Sheet{' '}
        <input
          data-testid="sheet-id-input"
          value={input}
          onChange={(e) => {
            setInput(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-load" disabled={load.isPending}>
        Load
      </button>{' '}
      {sheetId && (
        <span>
          Active sheet: <strong data-testid="sheet-current-id">{sheetId}</strong>
        </span>
      )}
      {error && (
        <p role="alert" data-testid="sheet-load-error">
          {error}
        </p>
      )}
    </form>
  );
}
