/**
 * A period on a sheet: its name (unique on the sheet), its from and to dates, inclusive, whether it
 * is closed, and the due-total fixed when it was closed (null while open). A soft-closed period is
 * closed with {@code soft} set: its figures are fixed, but claims dated inside it can still change.
 */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
        BigDecimal closedTotal, boolean soft) {

    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this(sheetId, name, from, to, false, null, false);
    }

    /** Whether the two periods share a day. */
    public boolean overlaps(Period other) {
        return !from.isAfter(other.to) && !other.from.isAfter(to);
    }

    /** Whether the date falls in the period. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }

    /** This period, closed with its due-total fixed. */
    public Period close(BigDecimal total) {
        return new Period(sheetId, name, from, to, true, total, false);
    }

    /** This period, soft-closed with its due-total fixed. */
    public Period softClose(BigDecimal total) {
        return new Period(sheetId, name, from, to, true, total, true);
    }

    /** Whether it is closed for good: claims dated inside it cannot change. */
    public boolean hardClosed() {
        return closed && !soft;
    }

    /** This period, reopened: its due-total live again. */
    public Period reopen() {
        return new Period(sheetId, name, from, to, false, null, false);
    }
}
package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The sheet store. */
@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet with this id, created empty (its today the real date) when never loaded before. */
    public Sheet loadOrCreate(String id) {
        jdbc.update("MERGE INTO sheet USING (VALUES (CAST(? AS VARCHAR(200)), CAST(? AS DATE))) s(id, today)"
                + " ON sheet.id = s.id WHEN NOT MATCHED THEN INSERT (id, today) VALUES (s.id, s.today)",
                id, Date.valueOf(LocalDate.now()));
        return find(id);
    }

    /** The sheet with this id, or null when it was never loaded. */
    public Sheet find(String id) {
        List<Sheet> found = jdbc.query("SELECT id, today, archived FROM sheet WHERE id = ?",
                (rs, n) -> new Sheet(rs.getString("id"), rs.getDate("today").toLocalDate(),
                        rs.getBoolean("archived")), id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The sheet's today: the date the sheet uses instead of the real clock. */
    public LocalDate today(String id) {
        Sheet sheet = find(id);
        return sheet == null ? LocalDate.now() : sheet.today();
    }

    public void saveToday(String id, LocalDate today) {
        jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", Date.valueOf(today), id);
    }

    /** Archive the sheet: true when this call archived it, false when it already was. */
    public boolean archive(String id) {
        return jdbc.update("UPDATE sheet SET archived = TRUE WHERE id = ? AND archived = FALSE", id) > 0;
    }

    /** Whether the sheet has been archived; false for a sheet never loaded. */
    public boolean isArchived(String id) {
        Sheet sheet = find(id);
        return sheet != null && sheet.archived();
    }
}

