export async function retire(page: Page, personId: string, date: string): Promise<boolean> {
  const r = row(page, personId);
  const done = async () => (await r.count()) === 0 || await shown(r.getByTestId('person-retired')) === 'yes';
  const already = await done();
  await r.getByTestId('person-retire-date').fill(date);
  await r.getByTestId('person-retire').click();
  return until(page, done, r.getByTestId('person-error'), 'retire', already);
}

/** Take a statement for the person: true once the row's statement count has moved on. */
export async function statement(page: Page, personId: string): Promise<boolean> {
  const r = row(page, personId);
  const was = await shown(r.getByTestId('person-statement-count'));
  await r.getByTestId('person-statement').click();
  return until(page, async () => await shown(r.getByTestId('person-statement-count')) !== was,
    r.getByTestId('person-error'), 'statement');
}

/** Take the person's statement as of a date: true once the statement count has moved on. */
export async function statementAsOf(page: Page, personId: string, date: string): Promise<boolean> {
  const r = row(page, personId);
  const was = await shown(r.getByTestId('person-statement-count'));
  await r.getByTestId('person-statement-asof').fill(date);
  await r.getByTestId('person-statement').click();
  return until(page, async () => await shown(r.getByTestId('person-statement-count')) !== was,
    r.getByTestId('person-error'), 'statement as of');
}

/** Cancel the person's last statement: true once the statement count has moved on. */
export async function unstate(page: Page, personId: string): Promise<boolean> {
  const r = row(page, personId);
  const was = await shown(r.getByTestId('person-statement-count'));
  await r.getByTestId('person-unstate').click();
  return until(page, async () => await shown(r.getByTestId('person-statement-count')) !== was,
    r.getByTestId('person-error'), 'cancel statement');
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { PersonHead, PersonRow } from '../../slots/defs/personRow';
import { peopleKey } from '../people/people';
import type { Person } from '../people/people';
import { claimsKey } from '../claims/claims';
import { useUser } from '../session/session';
import { useRowError } from '../people/rowError';

function StatementHead() {
  return (
    <>
      <th>Statements</th>
      <th>Stated</th>
      <th>Stated on</th>
      <th />
    </>
  );
}

// A person's statements: how many have been taken, the last one's due-total and date, and a button
// that takes the next. Taking one binds each of their claims that counts to its figure now; with a
// date beside it (on or before the sheet's today; blank: now) the statement is taken as the sheet
// stood at the end of that date, and that date is shown as its date. A steward
// can cancel the last one: the claims it bound become live again, and the one before it is shown.
function PersonStatement({ sheetId, person }: { sheetId: string; person: Person }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [asOf, setAsOf] = useState('');
  const [error, setError] = useRowError(person.id, 'statement');
  const once = useOnce();
  const take = useMutation({
    mutationFn: (date: string) =>
      postJson<Person>(
        `/api/sheets/${encodeURIComponent(sheetId)}/people/${encodeURIComponent(person.id)}/statement`,
        { asOf: date },
        user,
      ),
    onSuccess: () => {
      setAsOf('');
      return Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]);
    },
    onError: () => setError('That statement could not be taken.'),
  });
  const cancel = useMutation({
    mutationFn: () =>
      postJson<Person>(
        `/api/sheets/${encodeURIComponent(sheetId)}/people/${encodeURIComponent(person.id)}/unstate`,
        {},
        user,
      ),
    onSuccess: () =>
      Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]),
    onError: () => setError('That statement could not be cancelled.'),
  });

  const state = () => {
    setError('');
    once((done) => take.mutate(asOf.trim(), { onSettled: done }));
  };

  const unstate = () => {
    setError('');
    once((done) => cancel.mutate(undefined, { onSettled: done }));
  };

  return (
    <>
      <td data-testid="person-statement-count">{person.statementCount}</td>
      <td data-testid="person-stated-total">{person.statedTotal}</td>
      <td data-testid="person-statement-date">{person.statementDate}</td>
      <td>
        <input
          type="date"
          data-testid="person-statement-asof"
          value={asOf}
          onChange={(e) => {
            setAsOf(e.target.value);
            setError('');
          }}
        />{' '}
        <button type="button" data-testid="person-statement" onClick={state} disabled={take.isPending}>
          Statement
        </button>
        <button type="button" data-testid="person-unstate" onClick={unstate} disabled={cancel.isPending}>
          Cancel statement
        </button>
        {error && (
          <p role="alert" data-testid="person-error">
            {error}
          </p>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonHead.fill({ order: 30, Component: StatementHead }),
  PersonRow.fill({ order: 30, Component: PersonStatement }),
];

